def transform(grid):
 g=[r[:] for r in grid]
 # template signature is the existing 3/1 pair; apply only when one exists globally
 sig=[]
 for r,row in enumerate(grid):
  for c,x in enumerate(row):
   if x in (1,3): sig.append((c,x))
 if not sig:return g
 for r,row in enumerate(grid):
  cs=[c for c,x in enumerate(row) if x==4]
  if len(cs)==5:
   for rr in (r-1,r+1):
    if 0<=rr<len(grid):
     for c,x in enumerate(grid[rr]):
      if x==2 and abs(c-cs[2])==1:
       d=2*r-rr; g[d][c]=3; g[d][c+(2 if c<cs[2] else -2)]=1
 return g
